std::vector<int> V1 = {1, 5, 10};
std::vector<int> V2 = {1, 5, 8};
std::vector<int> V3 = {1, 5};

// Element-wise comparison (10 vs 8)
// Relational operators use lexicographical_compare
bool res1 = (V2 < V1); // true (8 < 10)

// Prefix rule: Shorter sequence is "less"
bool res2 = (V3 < V1); // true

// Explicit demonstration of the underlying algorithm
bool res3 = std::lexicographical_compare(
    V1.begin(), V1.end(), V2.begin(), V2.end()
); // false (V1 is NOT less than V2)
